      finish={...start,head:[60,128],shoulder:[84,137],hip:[152,162],nearLeg:[[152,162],[193,177],[233,193],[251,193]],farLeg:[[152,163],[193,181],[233,197]],nearArm:[[84,137],[87,194],[56,194]],farArm:[[84,137],[92,100],[100,58]]};arrow='M157 137v-28m-5 5 5-5 5 5';
