    const frame=(p,prop,offset,showArrow)=>`<g transform="translate(${offset},0)"><path d="M18 203h244" stroke="#555e4b" stroke-width="2"/>${figure(p,prop)}${showArrow?`<path d="${arrow}" fill="none" stroke="#b8c79c" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`:''}</g>`;
    const crops={'clamshells':[120,96],'forearm planks':[105,111],'russian twists':[65,151],'dead-bugs':[85,131],'bird-dogs':[85,131],'side-planks':[35,181]};
